// Generated by `just generate` from `src/plugins/dotclaude/slices/setup/lab/setup-command.test.ts`. Edit the source and run `just generate`.
// The hook lab of the `setup` command: `claude plugin test plugins/dotclaude` fires `command.run` with stubs.
// No CLI runs, no dialog opens, and no model call goes out.
// The stubs of `process.run` and of the `AskUserQuestion` call are the test's own, so the live CLI and the live dialog are not tested.

import type { On } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

/** The stubs of one test: the answer to each question in order, and the list of CLI calls. */
const stub = (on: On, answers: string[]) => {
  const calls: string[] = [];
  const asked: string[] = [];
  on("command.run", () => ({ text: "core" }));
  on("process.run", (_$, e) => {
    calls.push(e.argv.slice(3).join(" "));
    return {
      value: {
        exitCode: 0,
        stdout: `out ${e.argv.slice(3).join(" ")}`,
        stderr: "",
        isStdoutTruncated: false,
        isStderrTruncated: false,
      },
    };
  });
  on("tool.call", (_$, e, next) => {
    if (e.tool !== "AskUserQuestion") return next(e);
    const question = (e as unknown as { questions?: { question: string }[] })
      .questions?.[0]?.question;
    asked.push(question ?? "");
    const answer = answers.shift() ?? "Skip";
    return {
      result: {
        questions: [],
        answers: { [question ?? ""]: answer },
      },
    } as never;
  });
  return { calls, asked };
};

const typed = ($: Engine, command: string, args = "") =>
  $.command.run({
    command,
    args,
    origin: { kind: "composer" },
    presentation: { isFullscreen: false, columns: 80 },
  });

test("the command shows the previews and applies only after a yes", async ($: Engine, on: On) => {
  const { calls, asked } = stub(on, ["Apply", "Skip"]);
  const out = await typed($, "dotclaude:setup", "local");
  expect(calls).toEqual([
    "settings --scope local",
    "addons",
    "settings --scope local --apply",
  ]);
  expect(asked.length).toBe(2);
  expect(out.text).toContain("out settings --scope local");
});

test("a no to both questions applies nothing", async ($: Engine, on: On) => {
  const { calls } = stub(on, ["Skip", "Skip"]);
  await typed($, "dotclaude:setup", "user");
  expect(calls).toEqual(["settings --scope user", "addons"]);
});

test("a scope with a shell character runs unchanged", async ($: Engine, on: On) => {
  const { calls } = stub(on, []);
  const out = await typed($, "dotclaude:setup", "'user'");
  expect(out.text).toBe("core");
  expect(calls).toEqual([]);
});
